mapper.select:
SELECT m.id, m.conversation_id, m.sender_id, u.nickname AS sender_nickname, u.avatar_url AS sender_avatar_url, m.content, (m.sender_id = #{currentUserId}) AS mine, m.created_at FROM message m JOIN sys_user u ON u.id = m.sender_id WHERE m.conversation_id = #{conversationId}
AND m.id > #{afterId}
ORDER BY m.id ASC LIMIT 500
